PRAGMA foreign_keys = ON;
CREATE TABLE stores (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organization(id), name TEXT NOT NULL, config_version INTEGER NOT NULL DEFAULT 1, config_json TEXT NOT NULL CHECK(json_valid(config_json)), updated_at INTEGER NOT NULL);
CREATE TABLE restaurant_tables (id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES stores(id), name TEXT NOT NULL, UNIQUE(store_id,id));
CREATE TABLE table_sessions (id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES stores(id), table_id TEXT NOT NULL, locale TEXT NOT NULL CHECK(locale IN ('ja','en')), status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')), guest_count INTEGER NOT NULL CHECK(guest_count > 0), cart_version INTEGER NOT NULL DEFAULT 0 CHECK(cart_version>=0), cart_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(cart_json)), mutation_id TEXT, voice_state TEXT NOT NULL DEFAULT 'stopped' CHECK(voice_state IN ('active','stopped','error')), voice_session_id TEXT, active_turn_id TEXT, staff_called INTEGER NOT NULL DEFAULT 0, plan_json TEXT CHECK(plan_json IS NULL OR json_valid(plan_json)), opened_at INTEGER NOT NULL, closed_at INTEGER, FOREIGN KEY(store_id,table_id) REFERENCES restaurant_tables(store_id,id));
CREATE UNIQUE INDEX table_sessions_one_open ON table_sessions(table_id) WHERE status='open';
CREATE TABLE devices (id TEXT PRIMARY KEY, token_hash TEXT NOT NULL UNIQUE, store_id TEXT NOT NULL REFERENCES stores(id), table_id TEXT NOT NULL, approved_by TEXT NOT NULL REFERENCES user(id), revoked_at INTEGER, created_at INTEGER NOT NULL, FOREIGN KEY(store_id,table_id) REFERENCES restaurant_tables(store_id,id));
CREATE TABLE device_assignments (user_code TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES stores(id), table_id TEXT NOT NULL, approved_by TEXT NOT NULL REFERENCES user(id), created_at INTEGER NOT NULL, FOREIGN KEY(store_id,table_id) REFERENCES restaurant_tables(store_id,id));
CREATE TABLE confirmations (id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES stores(id), table_session_id TEXT NOT NULL REFERENCES table_sessions(id), cart_version INTEGER NOT NULL, config_version INTEGER NOT NULL, channel TEXT NOT NULL CHECK(channel IN ('gui','voice')), voice_session_id TEXT, created_turn_id TEXT, read_at INTEGER, status TEXT NOT NULL CHECK(status IN ('pending','read','invalid','submitted')), snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)), expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX confirmations_session ON confirmations(table_session_id,created_at);
CREATE TABLE orders (id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES stores(id), table_session_id TEXT NOT NULL REFERENCES table_sessions(id), snapshot_id TEXT NOT NULL UNIQUE REFERENCES confirmations(id), idempotency_key TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('submitted','accepted','served','cancelled','rejected')), snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)), total INTEGER NOT NULL CHECK(total>=0), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(table_session_id,idempotency_key));
CREATE TABLE payments (id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES stores(id), table_session_id TEXT NOT NULL REFERENCES table_sessions(id), idempotency_key TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('payment','adjustment')), amount INTEGER NOT NULL, reason TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES user(id), created_at INTEGER NOT NULL, UNIQUE(table_session_id,idempotency_key));
CREATE TABLE table_events (cursor INTEGER PRIMARY KEY AUTOINCREMENT, store_id TEXT NOT NULL REFERENCES stores(id), table_session_id TEXT REFERENCES table_sessions(id), kind TEXT NOT NULL, data_json TEXT NOT NULL CHECK(json_valid(data_json)), created_at INTEGER NOT NULL);
CREATE INDEX table_events_store_cursor ON table_events(store_id,cursor);
CREATE INDEX table_events_session_cursor ON table_events(table_session_id,cursor);
CREATE TABLE config_drafts (id TEXT PRIMARY KEY, store_id TEXT NOT NULL REFERENCES stores(id), base_version INTEGER NOT NULL, version INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL CHECK(status IN ('draft','ready','published','discarded')), config_json TEXT NOT NULL CHECK(json_valid(config_json)), errors_json TEXT NOT NULL DEFAULT '[]', created_by TEXT NOT NULL REFERENCES user(id), publish_key TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(store_id,publish_key));
CREATE TABLE config_releases (store_id TEXT NOT NULL REFERENCES stores(id), version INTEGER NOT NULL, config_json TEXT NOT NULL CHECK(json_valid(config_json)), published_by TEXT NOT NULL REFERENCES user(id), created_at INTEGER NOT NULL, PRIMARY KEY(store_id,version));
CREATE TABLE voice_turns (id TEXT PRIMARY KEY, voice_session_id TEXT NOT NULL, table_session_id TEXT NOT NULL REFERENCES table_sessions(id), store_id TEXT NOT NULL REFERENCES stores(id), status TEXT NOT NULL CHECK(status IN ('started','completed','interrupted','failed')), started_at INTEGER NOT NULL, ended_at INTEGER);
CREATE INDEX voice_turns_session ON voice_turns(voice_session_id,started_at);
